import{TASKS03,CANDIDATES03,EXERCISES03,metricsReport,assess03,checkExercise03,copy}from'./metrics03.mjs';import{describeError02}from'./legality02.mjs';import{board}from'../lessons/02/teaching/visuals.mjs';
const esc=s=>String(s).replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;');
export function lab03Page({code,task,quizBlock=''}){return`<main id="main" class="wrap focused-lesson"><header class="focused-hero"><div class="breadcrumbs"><a href="../../index.html">课程</a> / Lab 03</div><h1>摆紧以后，为什么密度还没变？</h1><p class="lead">先说清比较的条件和分母，再判断你的改动有没有改善目标。</p><nav class="focused-nav" aria-label="本课学习路径"><a href="#video">01 互动教学</a><a href="#lab">02 综合 Lab · Python</a><a href="#quiz">03 课后习题</a></nav></header><section id="video" class="focused-section"><span id="film"></span><span class="eyebrow">01 / LEARN</span><h2>互动讲解</h2><p class="small">先看一遍，也可以随时暂停，点图里的模块试一试。</p><iframe id="interactive-teaching-frame" title="Lab3互动教学" src="teaching/?embed=1&v=metrics-1" allow="autoplay; fullscreen" scrolling="no" style="width:100%;height:850px;border:0;display:block"></iframe></section>
<section id="lab" class="focused-section"><span class="eyebrow">02 / EXPERIMENT</span><h2>换条件、查公式，再比较目标</h2><p>三项任务分别检验平移不变量、固定外框筛选，以及宽度和面积的取舍。每题的模块清单与外框都写在题目里。</p><label>选择任务 <select id="lab03-task">${TASKS03.map(t=>`<option value="${t.id}">${esc(t.title)}</option>`).join('')}</select></label><p id="lab03-prompt"></p><button id="lab03-reset">重置当前任务</button><div id="lab03-candidates"></div><div id="lab03-board" class="lab02-board"></div><div id="lab03-table" class="table-scroll"></div><div id="lab03-controls"><p id="lab03-move-note"></p><label id="lab03-select-label">选中模块 <select id="lab03-selected"></select></label> <button data-lab03-move="-1,0" aria-label="向左移动">←</button> <button data-lab03-move="0,1" aria-label="向上移动">↑</button> <button data-lab03-move="0,-1" aria-label="向下移动">↓</button> <button data-lab03-move="1,0" aria-label="向右移动">→</button> <button id="lab03-undo">撤销</button></div><p id="lab03-status" role="status"></p><div id="lab03-evidence"></div><label>写下你的计算和判断<textarea id="lab03-explanation" rows="3" style="display:block;width:100%"></textarea></label><button id="lab03-check" class="primary">检查并保存</button> <button id="lab03-hint">需要一点提示</button><p id="lab03-result" role="status" style="white-space:pre-line"></p>
<article id="python" class="python-integrated"><h3>Python Lab：返回一份有依据的评价报告</h3><p>${esc(task.prompt.zh)}</p><details><summary>返回字段与检查规则</summary><p>rows、outline、catalog沿用Lab2格式。已提供完整validate_layout，不需要重写。module_area来自完整catalog，outline_area=W×H；bbox为xmin/ymin/xmax/ymax/width/height/area。空rows或有非有限数值、非正尺寸时bbox=None；其余有限正尺寸行即使非法，也可以保留诊断包围盒。</p><p>只有布局合法时，才返回outline_density=模块面积/外框面积、packing_density=模块面积/包围盒面积、outline_dead=外框面积−模块面积、bbox_dead=包围盒面积−模块面积。非法时这四项全部为None。密度返回0到1的比例，不是百分数。</p><p>legal和errors沿用Lab2检查结果。你要区分“能计算一份诊断几何”与“有资格作为优化结果”；不能只因为分母大于0就给分。</p><p>${task.tests.length}项检查只是基线。再写一个你自己的测试，说明它能排除哪种错误公式。</p></details><textarea id="python-source" class="python-editor" aria-label="Python source code" spellcheck="false">${esc(code)}</textarea><div class="python-toolbar"><button id="python-run" class="primary">运行综合检查</button><button id="python-stop" disabled>停止</button><button id="python-reset">恢复模板</button></div><pre id="python-output" class="python-output" role="status">尚未检查。修改代码后，需要重新运行。</pre></article></section>
<section id="quiz" class="focused-section"><span class="eyebrow">03 / EXPLAIN</span><h2>课后练习：每个结论都带上分母和条件</h2><p>除了数值，也写出比较依据。做完后可以对照参考要点检查。</p>${EXERCISES03.map(q=>`<article class="extended-exercise" data-exercise03="${q.id}"><h3>${esc(q.title)}</h3><p>${esc(q.prompt)}</p><div class="exercise-fields">${q.fields.map(([key,label])=>`<label>${esc(label)} <input type="number" step="any" data-field="${key}"></label>`).join('')}</div><label>你的推理<textarea data-explain rows="3"></textarea></label><button data-check>检查并保存</button> <button data-reveal>查看参考要点</button><p data-result role="status"></p><p data-rubric hidden>${esc(q.rubric)}</p></article>`).join('')}${quizBlock}</section></main>`;}
export function bindLab03({progress,save}){const $=s=>document.querySelector(s),root=$('#lab03-board');let task=TASKS03[0],rows=copy(task.rows),selected=0,choice='wide',history=[],edited=false,hint=false,drag=null;progress.lab03Submissions=progress.lab03Submissions||{};progress.exercises03=progress.exercises03||{};
 function stopDrag(){if(!drag)return;const d=drag;drag=null;rows=copy(d.rows);try{if(root.hasPointerCapture(d.pointerId))root.releasePointerCapture(d.pointerId);}catch{}}
 function render(){const active=root.contains(document.activeElement)?document.activeElement.closest('[data-row]')?.getAttribute('data-row'):null,r=metricsReport(rows,task.outline,task.catalog);root.innerHTML=`<svg viewBox="0 0 960 540" role="group" aria-label="布局实验网格"><defs><pattern id="collision" width="8" height="8" patternUnits="userSpaceOnUse" patternTransform="rotate(45)"><rect width="8" height="8" fill="#efc2ad"/><path d="M0 0V8" stroke="#a74330" stroke-width="3"/></pattern></defs>${board(rows,task.outline,{x:70,y:60,w:810,h:415})}</svg>`;$('#lab03-prompt').textContent=task.prompt;$('#lab03-table').innerHTML=`<table style="width:100%"><thead><tr><th>模块</th><th>x</th><th>y</th><th>宽×高</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${esc(r[0])}${task.id==='tradeoff'&&r[0]!=='E'?'（固定）':''}</td><td>${r[1]}</td><td>${r[2]}</td><td>${r[3]}×${r[4]}</td></tr>`).join('')}</tbody></table>`;$('#lab03-status').textContent=r.legal?'当前布局通过Lab2检查，可以据此计算有效指标。':'当前不能计有效分数：'+r.errors.map(describeError02).join('，');$('#lab03-controls').hidden=task.id==='selection';$('#lab03-select-label').hidden=task.id!=='tradeoff';$('#lab03-move-note').textContent=task.id==='translation'?'所有模块一起移动；也可以拖动任意一块，整体平移。':'只移动E，其余四块保持原位。';$('#lab03-selected').innerHTML=rows.map((r,i)=>`<option value="${i}" ${task.id==='tradeoff'&&r[0]!=='E'?'disabled':''} ${i===selected?'selected':''}>${esc(r[0])}</option>`).join('');$('#lab03-undo').disabled=!history.length;for(const b of document.querySelectorAll('[data-candidate03]'))b.setAttribute('aria-pressed',String(b.dataset.candidate03===choice));if(active!=null)root.querySelector('[data-row="'+active+'"]')?.focus({preventScroll:true});}
 function load(id){stopDrag();task=TASKS03.find(t=>t.id===id);rows=copy(task.rows);selected=task.id==='tradeoff'?4:0;choice='wide';history=[];edited=false;hint=!!progress.lab03Submissions[task.id]?.hintUsed;$('#lab03-result').textContent='';$('#lab03-explanation').value='';$('#lab03-candidates').innerHTML=task.id==='selection'?CANDIDATES03.map(c=>`<button data-candidate03="${c.id}" aria-pressed="false">查看${esc(c.title)}</button>`).join(' '):'';for(const b of document.querySelectorAll('[data-candidate03]'))b.onclick=()=>{choice=b.dataset.candidate03;rows=copy(CANDIDATES03.find(c=>c.id===choice).rows);render();};const fields=task.id==='translation'?[['width','当前盒宽'],['height','当前盒高'],['area','真包围盒面积'],['bad','错误公式的结果']]:task.id==='selection'?[['wide','X的几何盒面积'],['tall','Y的几何盒面积'],['fake','Z的几何盒面积']]:[['area','当前盒面积'],['dead','盒内空余'],['outline','外框密度（%）'],['packing','包围盒密度（%）']];$('#lab03-evidence').innerHTML=`<div class="exercise-fields">${fields.map(([key,label])=>`<label>${label} <input id="lab03-${key}" type="number" step="any"></label>`).join('')}</div>`+(task.id==='tradeoff'?'<label>盒面积比起始27改善了吗？ <select id="lab03-improved"><option value="">请选择</option><option value="no">没有改善</option><option value="yes">改善了</option></select></label>':'');render();}
 function applyMove(dx,dy){if(task.id==='selection')return;if(task.id==='tradeoff'&&rows[selected]?.[0]!=='E'){render();$('#lab03-result').textContent='本题只有E可以移动。';return;}history.push(copy(rows));if(task.id==='translation')rows.forEach(r=>{r[1]+=dx;r[2]+=dy;});else{rows[selected][1]+=dx;rows[selected][2]+=dy;}edited=true;$('#lab03-result').textContent='';render();}
 $('#lab03-task').onchange=e=>load(e.target.value);$('#lab03-reset').onclick=()=>load(task.id);$('#lab03-selected').onchange=e=>selected=Number(e.target.value);for(const b of document.querySelectorAll('[data-lab03-move]'))b.onclick=()=>applyMove(...b.dataset.lab03Move.split(',').map(Number));$('#lab03-undo').onclick=()=>{stopDrag();if(history.length){rows=history.pop();edited=true;render();}};
 root.onkeydown=e=>{const row=e.target.closest('[data-row]');if(!row)return;selected=Number(row.dataset.row);const d={ArrowLeft:[-1,0],ArrowRight:[1,0],ArrowUp:[0,1],ArrowDown:[0,-1]}[e.key];if(d){e.preventDefault();applyMove(...d);}};root.onpointerdown=e=>{const row=e.target.closest('[data-row]');if(!row||task.id==='selection')return;selected=Number(row.dataset.row);if(task.id==='tradeoff'&&rows[selected][0]!=='E'){render();$('#lab03-result').textContent='本题只有E可以移动。';return;}const svg=root.querySelector('svg'),p=new DOMPoint(e.clientX,e.clientY).matrixTransform(svg.getScreenCTM().inverse());drag={rows:copy(rows),p,unit:Number(svg.querySelector('[data-board]').dataset.unit),pointerId:e.pointerId,index:selected};row.focus({preventScroll:true});root.setPointerCapture(e.pointerId);e.preventDefault();};root.onpointermove=e=>{if(!drag)return;const p=new DOMPoint(e.clientX,e.clientY).matrixTransform(root.querySelector('svg').getScreenCTM().inverse()),dx=Math.round((p.x-drag.p.x)/drag.unit),dy=-Math.round((p.y-drag.p.y)/drag.unit);rows=copy(drag.rows);if(task.id==='translation')rows.forEach(r=>{r[1]+=dx;r[2]+=dy;});else{rows[drag.index][1]+=dx;rows[drag.index][2]+=dy;}render();};root.onpointerup=()=>{const d=drag;drag=null;if(d&&JSON.stringify(rows)!==JSON.stringify(d.rows)){history.push(d.rows);edited=true;}if(d)try{root.releasePointerCapture(d.pointerId);}catch{}render();};root.onpointercancel=()=>{stopDrag();render();};
 $('#lab03-hint').onclick=()=>{hint=true;progress.lab03Submissions[task.id]={...(progress.lab03Submissions[task.id]||{}),hintUsed:true};save();$('#lab03-result').textContent=task.hint;};$('#lab03-check').onclick=()=>{const e={choice};for(const key of['width','height','area','bad','wide','tall','fake','dead','outline','packing','improved'])e[key]=$('#lab03-'+key)?.value;const result=assess03(task.id,rows,e);if(task.id!=='selection'&&!edited)result.errors.unshift('先实际移动布局，再提交你的计算。');const explanation=$('#lab03-explanation').value,ok=result.ok&&(task.id==='selection'||edited);progress.lab03Submissions[task.id]={version:1,rows:copy(rows),evidence:e,numericPassed:ok,explanation,hintUsed:hint,explanationStatus:'submitted-not-graded'};save();$('#lab03-result').textContent=result.errors.length?result.errors.join('\n'):explanation.trim().length<30?'条件和数值通过，请再写清楚你选择的分母和判断依据。':'条件和数值通过，解释已保存。请确认你比较的是同一个目标。';};
 for(const article of document.querySelectorAll('[data-exercise03]')){const id=article.dataset.exercise03,saved=progress.exercises03[id]||{};for(const input of article.querySelectorAll('[data-field]'))input.value=saved.values?.[input.dataset.field]??'';article.querySelector('[data-explain]').value=saved.explanation||'';let revealed=!!saved.revealed;article.querySelector('[data-check]').onclick=()=>{const values=Object.fromEntries([...article.querySelectorAll('[data-field]')].map(e=>[e.dataset.field,e.value])),explanation=article.querySelector('[data-explain]').value,ok=checkExercise03(id,values);progress.exercises03[id]={values,explanation,numericPassed:ok,revealed,explanationStatus:'submitted-not-graded'};save();article.querySelector('[data-result]').textContent=!ok?'数值还不对，请核对最小坐标、分母和比较条件。':explanation.trim().length<30?'数值通过，请补上你的推理。':'数值通过，解释已保存。请按参考要点检查依据。'+(revealed?'（已查看参考）':'');};article.querySelector('[data-reveal]').onclick=()=>{revealed=true;article.querySelector('[data-rubric]').hidden=false;progress.exercises03[id]={...(progress.exercises03[id]||{}),revealed:true};save();article.querySelector('[data-result]').textContent='参考要点已显示，不计作独立完成的证明。';};}
 load(task.id);
}
